    return { field, control, valueNode };
  };

  const aControl = makeRange("a", -5, 5, 1);
  const bControl = makeRange("b", -10, 10, -3);
  const cControl = makeRange("c", -10, 10, 2);

  const form = htl.html`&lt;div class="p3-quadratic-panel-uza"&gt;
